    await ui.setSetting(pg_uma, "escalate-after", "1");
    await ui.setSetting(pg_uma, "default-grade", "B");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50", "from": "2026-03-10", "to": "2026-03-12"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C", "contact": "ben@x"}));
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C", "contact": "ADA@X", "tags": "c"}));
    expect(await ui.addPool(pg_uma, "P1")).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "50.00"})).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Cam", "share": "50.00", "from": "2026-03-01", "to": "2026-04-30"})).toBe(true);
    const pl_cam_1 = ui.must(await ui.addPlan(pg_uma, p_cam, {"amount": "12.50", "start": "2026-02-20", "end": "2026-04-30", "day": "1"}));
    const c_cam_0 = ui.must(await ui.addClaimTwice(pg_uma, p_cam, {"amount": "0.40", "date": "2026-03-09"}));
    expect(await ui.claimCount(pg_uma, p_cam)).toBe(1);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.editPerson(pg_vic, p_cam, {"grade": "A"})).toBe(true);
    expect(await ui.compareSheet(pg_vic, `${sheet}-p`)).toEqual([]);
    await ui.refresh(pg_uma);
    expect(await ui.search(pg_uma, "zz")).toEqual([]);
    expect(await ui.editClaim(pg_uma, c_cam_0, {"amount": "12.50"})).toBe(true);
    await ui.refresh(pg_uma);
    expect(await ui.setApprover(pg_uma, p_cam, "vic")).toBe(true);
    expect(await ui.periodAction(pg_uma, "P1", "close")).toBe(false);
    const c_cam_1 = ui.must(await ui.quickAdd(pg_uma, {"name": "Cam", "amount": "0.04"}, p_cam));
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    expect(await ui.bulkReassign(pg_wes, [c_cam_1, c_cam_0], "Cam")).toEqual({ reassigned: 2, refused: 0 });
    expect(await ui.statementAsOf(pg_wes, p_cam, "2026-03-01")).toBe(false);
    expect(await ui.statement(pg_wes, p_ada)).toBe(true);
    expect(await ui.setRate(pg_wes, {"grade": "B", "pct": "20.00", "from": "2026-04-20"})).toBe(true);
    await ui.refresh(pg_wes);
