#!/usr/bin/env bash
# Build, start the whole app, run the Playwright specs present in e2e/specs, then stop.
set -euo pipefail
cd "$(dirname "$0")/.."

export PORT="${PORT:-3000}"
export BASE_URL="http://localhost:${PORT}"
# Known audit file, shared by the app (bin/start) and the specs (support/audit.ts). Absolute.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

# Refuse to run against a server that is not ours: an app left running on $PORT (an earlier
# bin/start that was never stopped, another sandbox) would take the tests and fail them all.
if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then
  echo "bin/e2e: something is already serving on port ${PORT}; stop it (bin/stop) or set PORT to a free port" >&2
  exit 2
fi

bin/build
bin/start
cleanup() { bin/stop || true; }
trap cleanup EXIT

# Wait for readiness (Actuator health), then run the Playwright specs against BASE_URL. A loaded
# machine can take minutes to bring the JVM up; running the specs before it is ready fails every
# one of them for no reason, so wait long and fail loudly rather than run against nothing.
ready=0
for i in $(seq 1 300); do
  if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then ready=1; break; fi
  sleep 1
done
if [ "$ready" != 1 ]; then
  echo "bin/e2e: the app did not become healthy on port ${PORT} within 300s; see .run/app.log" >&2
  exit 2
fi

# Install deps + the Chromium browser (both cached after first run), then run the specs.
( cd e2e && npm ci --silent && npx --yes playwright install chromium && npx playwright test )
# A steward undoes the transfer that brought the person to this sheet, on the sheet's today they arrived: they are
# transferred back to the sheet they came from by the transfer rules. Refused (400, nothing written) for anyone else,
# any later day, or a person who did not arrive by transfer. Responds with this sheet's people.
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: undo
undo:
  class: net.officefloor.hq.app.person.UndoTransfer
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPeople
  govern: [ transaction ]
handle:
  class: net.officefloor.hq.app.person.HandleInvalidPerson
# A steward merges the person into another on the sheet ({"into": <person id>}): refused (400, nothing written) for
# anyone else, the same person, or either of them retired. Responds with the sheet's people.
validate:
  class: net.officefloor.hq.app.person.ValidateMerge
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: merge
merge:
  class: net.officefloor.hq.app.person.MergePerson
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPeople
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Undoes the transfer that brought the person to this sheet, by the rules of {@link PersonTransferrer}. */
public class UndoTransfer {
    public void undo(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Person person,
            PersonTransferrer transferrer) throws InvalidPersonException {
        transferrer.undo(sheet, user, person);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Merges the person into another on the sheet by the rules of {@link PersonMerger}. */
public class MergePerson {
    public void merge(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val MergeRequest body,
            @Val Person person, PersonMerger merger) throws InvalidPersonException {
        merger.merge(sheet, user, person, body.into());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the merge body once, refusing one that names no person. */
public class ValidateMerge {
    public void validate(@RequestBody MergeRequest request, Out<MergeRequest> body) throws InvalidPersonException {
        if (request == null || request.into() == null) {
            throw new InvalidPersonException("A merge names the person merged into");
        }
        body.set(request);
    }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { useIsLatest } from '../../query/useIsLatest';
import { byUser } from '../session/session';
import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { peopleKey, peoplePath, personActionKey } from './people';
import type { Person } from './people';

function TransferHeader() {
  return <th />;
}

// The id of the sheet to transfer this person to, and the button that transfers them. Only a steward may; the server
// refuses a retired person, this sheet's own id, or a contact already on the other sheet; a name or alias already there
// merges them into that person (refused when that person is retired or the names are on several people). A transfer
// drops the person's claims, patron links and pool memberships here, so everything on both sheets is re-read.
function PersonTransfer({ sheet, user, person }: { sheet: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const [to, setTo] = useState('');
  const transfer = useMutation({
    mutationKey: personActionKey(sheet, person.id),
    mutationFn: (target: string) =>
      postJson<Person[]>(byUser(`${peoplePath(sheet)}/${person.id}/transfer`, user), { to: target }),
    onSuccess: async (updated, target) => {
      await queryClient.invalidateQueries({
        predicate: (q) =>
          (q.queryKey.includes(sheet) && q.queryKey[0] !== 'sheet' && q.queryKey[0] !== 'people') ||
          q.queryKey.includes(target),
      });
      queryClient.setQueryData(peopleKey(sheet), updated);
      setTo('');
    },
  });
  const act = useSubmitOnce(transfer);
  const latest = useIsLatest(personActionKey(sheet, person.id), transfer.submittedAt);

  return (
    <td>
      <input
        data-testid="person-transfer-to"
        placeholder="transfer to sheet…"
        value={to}
        onChange={(e) => {
          setTo(e.target.value);
          transfer.reset();
        }}
      />{' '}
      <button
        type="button"
        data-testid="person-transfer"
        disabled={transfer.isPending}
        onClick={() => act(to.trim())}
      >
        Transfer
      </button>
      {transfer.isError && latest && (
        <span data-testid="person-error" role="alert">
          {' '}Only a steward may transfer a person, not retired, to another sheet without their contact, merging only into one person who is not retired.
        </span>
      )}
    </td>
  );
}

// The button that undoes the transfer that brought this person here, sending them back to the sheet they came from by
// the transfer rules. The server refuses anyone but a steward, any day but the sheet's today they arrived, and a person
// who did not arrive by transfer; both sheets are re-read as for a transfer.
function PersonTransferUndo({ sheet, user, person }: { sheet: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const undo = useMutation({
    mutationKey: personActionKey(sheet, person.id),
    mutationFn: () => postJson<Person[]>(byUser(`${peoplePath(sheet)}/${person.id}/transfer-undo`, user), {}),
    onSuccess: async (updated) => {
      const target = person.origin;
      await queryClient.invalidateQueries({
        predicate: (q) =>
          (q.queryKey.includes(sheet) && q.queryKey[0] !== 'sheet' && q.queryKey[0] !== 'people') ||
          (target != null && q.queryKey.includes(target)),
      });
      queryClient.setQueryData(peopleKey(sheet), updated);
    },
  });
  const act = useSubmitOnce(undo);
  const latest = useIsLatest(personActionKey(sheet, person.id), undo.submittedAt);

  return (
    <td>
      <button
        type="button"
        data-testid="person-transfer-undo"
        disabled={undo.isPending}
        onClick={() => act(undefined)}
      >
        Undo transfer
      </button>
      {undo.isError && latest && (
        <span data-testid="person-error" role="alert">
          {' '}Only a steward may undo a transfer, on the day the person arrived by it.
        </span>
      )}
    </td>
  );
}

export const contributions = [
  PersonColumnHeaders.fill({ order: 75, Component: TransferHeader }),
  PersonColumns.fill({ order: 75, Component: PersonTransfer }),
  PersonColumnHeaders.fill({ order: 76, Component: TransferHeader }),
  PersonColumns.fill({ order: 76, Component: PersonTransferUndo }),
];
